[CmdletBinding()]
param([Parameter(Mandatory)][ValidateSet('supervisor-plan','supervisor-preview','supervisor-request-approval','supervisor-start','supervisor-status','supervisor-reconcile','supervisor-stop-monitor','supervisor-fail')][string]$Operation,[Parameter(Mandatory)][string]$TaskId,[string]$RunId,[string]$AdapterId,[ValidateRange(1,3600)][int]$TimeoutSeconds,[string]$ErrorDetails,[string]$StoreRoot=(Join-Path $PSScriptRoot 'Store'),[switch]$DryRun)
$ErrorActionPreference='Stop';Import-Module (Join-Path $PSScriptRoot 'Repato.ProcessSupervisor.psm1') -Force -WarningAction SilentlyContinue
$result=switch($Operation){'supervisor-plan'{New-SupervisorPlan $StoreRoot $TaskId $AdapterId $TimeoutSeconds -DryRun:$DryRun};'supervisor-preview'{Get-SupervisorPreview $StoreRoot $TaskId $RunId};'supervisor-request-approval'{Request-SupervisorApproval $StoreRoot $TaskId $RunId};'supervisor-start'{Invoke-SupervisorStart $StoreRoot $TaskId $RunId -DryRun:$DryRun};'supervisor-status'{Get-SupervisorStatus $StoreRoot $TaskId};'supervisor-reconcile'{Invoke-SupervisorReconcile $StoreRoot $TaskId};'supervisor-stop-monitor'{Stop-SupervisorMonitor $StoreRoot $TaskId $RunId};'supervisor-fail'{Fail-SupervisorRun $StoreRoot $TaskId $RunId $ErrorDetails}};$result|ConvertTo-Json -Depth 20
